// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { MARK_REVEAL, useMarkPhase } from "@/hooks/use-mark-ink";
import { useInk, useMergedRef } from "@/lib/ink/vue";
import { bracketRecipe, type BracketKind } from "@/lib/ink/recipes/bracket-ink";
import type { MarkPen, MarkWeight } from "@/lib/ink/recipes/text-marks-ink";
import { cn } from "@/lib/utils";
const Bracket = defineUi<UI.ComponentProps<"div"> & {
  kind?: BracketKind;
  side?: "start" | "end";
  tone?: MarkPen;
  weight?: MarkWeight;
  inset?: number;
  animate?: boolean;
  show?: boolean;
  delay?: number;
  seed?: string | number;
}>("Bracket", ["kind", "side", "tone", "weight", "inset", "animate", "show", "delay", "seed", "class", "style"], (_props, {
  slots: _slots
}) => {
  const kind = computed(() => _props["kind"] === undefined ? "square" as const : _props["kind"]);
  const side = computed(() => _props["side"] === undefined ? "start" as const : _props["side"]);
  const tone = computed(() => _props["tone"] === undefined ? "ink" as const : _props["tone"]);
  const weight = computed(() => _props["weight"] === undefined ? "regular" as const : _props["weight"]);
  const inset = computed(() => _props["inset"] === undefined ? 8 : _props["inset"]);
  const animate = computed(() => _props["animate"] === undefined ? false : _props["animate"]);
  const show = computed(() => _props["show"] === undefined ? true : _props["show"]);
  const delay = computed(() => _props["delay"]);
  const seed = computed(() => _props["seed"]);
  const className = computed(() => _props["class"]);
  const style = computed(() => _props["style"]);
  const children = renderValue(() => readSlot(_slots.default));
  const ref = computed(() => _props["ref"]);
  const props = computed(() => omitProps(_props, ["kind", "side", "tone", "weight", "inset", "animate", "show", "delay", "seed", "class", "style", "children", "ref"]));
  const {
    hostRef,
    hostProps,
    node
  } = useInk(() => ({
    recipe: bracketRecipe,
    params: {
      kind: kind.value,
      side: side.value,
      tone: tone.value,
      weight: weight.value,
      inset: inset.value,
      animate: animate.value
    },
    kind: "bracket" as const,
    seed: seed.value
  }));
  const _hook15 = useMarkPhase(() => ({
    animate: animate.value,
    show: show.value
  }));
  const phaseRef = computed(() => _hook15.value.phaseRef);
  const phaseProps = computed(() => _hook15.value.phaseProps);
  const ready = computed(() => !!node.value && show.value);
  return () => {
    return <div data-slot="bracket" data-kind={kind.value} data-side={side.value} ref={useMergedRef<HTMLElement>(hostRef, phaseRef.value, ref.value as UI.Ref<HTMLElement> | undefined)} {...domProps(ready.value ? hostProps.value : {})} {...domProps(phaseProps.value)} style={cssStyle({
      ...(animate.value ? {
        "--ll-draw-delay": `${delay.value ?? 0}ms`
      } as UI.CSSProperties : undefined),
      ...style.value
    })} class={cn("relative isolate outline-none", side.value === "start" ? "ps-7" as const : "pe-7" as const, animate.value && MARK_REVEAL, className.value)} {...domProps(props.value)}>
      {ready.value ? node.value : null}
      {readSlot(_slots.default)}
    </div>;
  };
});
export { Bracket };

import { defineRecipe } from '@/lib/ink/recipes'
import { markRevealId, revealMark } from '@/lib/ink/recipes/mark-reveal-ink'
import { markPen, STRUCTURAL_DRY, type MarkPen, type MarkWeight } from '@/lib/ink/recipes/text-marks-ink'
import type { Rng } from '@/lib/ink/rng'
import { bracketLines } from '@/lib/ink/shapes'
import type { Line, Pt } from '@/lib/ink/types'

export type BracketKind = 'square' | 'curly' | 'round'

export interface BracketParams {
  kind: BracketKind
  side: 'start' | 'end'
  tone: MarkPen
  weight: MarkWeight
  inset: number
  animate?: boolean
}

function roundLines(rng: Rng, x: number, y: number, h: number, d: 1 | -1): Line[] {
  const tip = Math.min(11, Math.max(3.5, h * 0.13))
  const skew = rng.range(0.78, 1.28)
  const lean = rng.gauss(0, 0.014) * h
  const pts: Pt[] = []
  for (let i = 0; i <= 14; i++) {
    const t = i / 14
    pts.push([x + d * tip * (1 - Math.sin(Math.PI * t ** skew)) + lean * (t - 0.5) + rng.gauss(0, 0.12), y + h * t])
  }
  return [{ pts, o: { start: 'soft', end: 'flick', wobble: 0.6 } }]
}

export const bracketRecipe = defineRecipe<BracketParams>({
  id: 'bracket',
  kind: 'bracket',
  layers: ['rest'],
  pad: 12,
  draw(ink, { w, h }, p, ctx) {
    const { pen, width } = markPen(p.tone, p.weight, 18)
    const left = (p.side === 'start') === (ctx.dir !== 'rtl')
    const x = left ? p.inset : w - p.inset
    const trim = Math.min(6, h * 0.04)
    const H = Math.max(8, h - 2 * trim)
    const d = left ? 1 : -1
    const rng = ink.next('bracket')
    const lines = p.kind === 'round' ? roundLines(rng, x, trim, H, d) : bracketLines(rng, x, trim, H, { kind: p.kind, dir: d })
    ink.layer('rest', () => {
      if (p.animate) revealMark(ink, { id: markRevealId(ctx.seed, 'b'), lines, pen, box: { w, h }, pad: 14, width, opts: { dry: STRUCTURAL_DRY }, revealWidth: 5 })
      else ink.lines(lines, pen, { width, dry: STRUCTURAL_DRY })
    })
  },
})

